-- 90_VERIFY.sql — DMF0035 적용 확인 [20260827]
SELECT OBJECT_NAME, OBJECT_TYPE, STATUS FROM ALL_OBJECTS WHERE OWNER='SCM_MGR' AND OBJECT_NAME IN ('PKG_DMF0035', 'PKG_DMF0022', 'PKG_DMF0051', 'PKG_SCM0002');
SELECT COUNT(*) AS INVALID_CNT FROM ALL_OBJECTS WHERE OWNER='SCM_MGR' AND STATUS='INVALID' AND OBJECT_NAME IN ('PKG_DMF0035', 'PKG_DMF0022', 'PKG_DMF0051', 'PKG_SCM0002');
SELECT 'SCM_ADM_PROGRAM' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_PROGRAM WHERE PROGRAM_ID LIKE 'DMF0035%';  -- 기대 1
SELECT 'SCM_ADM_MNU_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_MNU_M WHERE MNU_ID LIKE 'DMF0035%';  -- 기대 1
SELECT 'SCM_ADM_USER_GR_MNU_MPG_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_USER_GR_MNU_MPG_M WHERE MNU_ID LIKE 'DMF0035%';  -- 기대 5
SELECT 'SCM_ADM_MNU_BTN_MPG_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID LIKE 'DMF0035%';  -- 기대 8
SELECT 'SCM_ADM_USER_GR_MNU_BTN_MPG_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_USER_GR_MNU_BTN_MPG_M WHERE MNU_ID LIKE 'DMF0035%';  -- 기대 40
SELECT 'SCM_ADM_API_M' T, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_API_M WHERE API_ID LIKE 'DMF0035%';  -- 기대 8
SELECT 'SCM_MST_SHEET_COLUMNS/Mkt Fcst Waterfall' T, COUNT(*) CNT FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='DMF0035' AND SHEET_NAME='Mkt Fcst Waterfall';  -- 기대 71
SELECT 'SCM_MST_SHEET_MEASURE/Mkt Fcst Waterfall' T, COUNT(*) CNT FROM SCM_MGR.SCM_MST_SHEET_MEASURE WHERE PROGRAM_ID='DMF0035' AND SHEET_NAME='Mkt Fcst Waterfall';  -- 기대 49
SELECT COUNT(*) AS GTT_CNT FROM ALL_TABLES WHERE OWNER='SCM_MGR' AND TEMPORARY='Y' AND TABLE_NAME IN ('GT_DM22_CALENDAR', 'GT_DM22_DM_MST_ITEM_SINGLE_A_V', 'GT_DM22_DM_MST_ITEM_SINGLE_B_V', 'GT_DM22_DM_MST_ITEM_SINGLE_ORI_V', 'GT_DM22_DM_MST_ITEM_SINGLE_V', 'GT_DM22_DM_MST_ITEM_SINGLE_V_T', 'GT_DM22_PROGRAM_ADD_MEASURE', 'GT_DM22_RAW_DATA', 'GT_DM22_RAW_DATA_TEMP40', 'GT_DM22_RAW_DATA_TEMP40_KEY', 'GT_DM22_RTF_ENERGY', 'GT_DM22_SCM_MST_SHEET_MEASURE', 'GT_DM22_SCM_MST_SITE', 'GT_DM22_SCM_MST_SITE_ITEM', 'GT_DM22_SELECT_MEASURE', 'GT_DM22_T', 'GT_DM22_T_COLUMN_SETUP', 'GT_DM22_T_PRICE', 'GT_DM22_V_VERSION_NO', 'GT_DM35_CALENDAR', 'GT_DM35_CAL_MONTH_END', 'GT_DM35_CAL_WEEK_END', 'GT_DM35_DM_PLN_MKT', 'GT_DM35_EDI_END_CUST', 'GT_DM35_EDI_SENDER', 'GT_DM35_ITEM_SINGLE_A', 'GT_DM35_ITEM_SINGLE_B', 'GT_DM35_ITEM_SINGLE_ORI', 'GT_DM35_ITEM_SINGLE_V', 'GT_DM35_RAW_DATA', 'GT_DM35_RAW_DATA_FINAL', 'GT_DM35_RPA_END_CUST', 'GT_DM35_SCP_ITEM_INFO', 'GT_DM35_SEL_MEASURE', 'GT_DM35_SITE_ITEM', 'GT_DM35_T', 'GT_DM35_TEMP_SCM_SITE', 'GT_DM35_TEMP_VMI_INV', 'GT_DM35_T_COLUMN_SETUP', 'GT_DM35_T_LAST_SETUP', 'GT_DM35_T_LAST_SETUP_C', 'GT_DM35_VERSION', 'GT_DM35_VMI_INV_RESULT', 'GT_DM51_RAW_DATA', 'GT_DM51_SCM_CITY', 'GT_DM51_SCM_MST_SITE_ITEM', 'GT_SPNC_SHPCHK_DUP', 'GT_SPNC_SHPCHK_NEW', 'GT_SPNC_SHPCHK_PLAN');  -- 기대 49

-- ── 22A/25A 종속 PROGRAM_ID(DMF0022/DMF0051) 메타 검증 [2026-08-27 DEP-PROGRAM] ──
SELECT 'SCM_MST_SHEET_COLUMNS/DMF0022/salesPlanWaterfall' T, COUNT(*) CNT FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='DMF0022' AND SHEET_NAME='salesPlanWaterfall';  -- 기대 65
SELECT 'SCM_MST_SHEET_MEASURE/DMF0022/Sales Plan Waterfall' T, COUNT(*) CNT FROM SCM_MGR.SCM_MST_SHEET_MEASURE WHERE PROGRAM_ID='DMF0022' AND SHEET_NAME='Sales Plan Waterfall';  -- 기대 31
SELECT 'SCM_MST_SHEET_COLUMNS/DMF0051/Biz Plan Waterfall' T, COUNT(*) CNT FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='DMF0051' AND SHEET_NAME='Biz Plan Waterfall';  -- 기대 61
SELECT 'SCM_MST_SHEET_MEASURE/DMF0051/Biz Plan Waterfall' T, COUNT(*) CNT FROM SCM_MGR.SCM_MST_SHEET_MEASURE WHERE PROGRAM_ID='DMF0051' AND SHEET_NAME='Biz Plan Waterfall';  -- 기대 9
SELECT PROGRAM_ID, COUNT(*) FROM SCM_MGR.SCM_ADM_EXCEL_COLUMNS WHERE PROGRAM_ID IN ('DMF0022','DMF0051') GROUP BY PROGRAM_ID;  -- 기대 0 합

-- ── V11~V13 조용한-실패 게이트 (hook #148 cloud-deploy-silent-failure-gates, 2026-08-28 — §4.7-B V11 미구현 재발 정정) ──
-- V11 메뉴 행 실존 + UNIT_TP_CD='D'/USE_YN='Y' (기대 1행) — 부재 시 SCM_ADM_USER_MNU_EDIT_AUTH_V INNER JOIN 으로 오류 없이 0행
SELECT 'V11-MNU' G, MNU_ID, UNIT_TP_CD, USE_YN FROM SCM_MGR.SCM_ADM_MNU_M WHERE MNU_ID='DMF0035';
-- V11-B 테스트 계정 권한 뷰 반환 행 (기대 ≥1, 조회 Division 포함) — <TEST_USER> 를 실제 로그인 ID 로
SELECT 'V11-AUTH' G, UNIT_ID, EDIT_YN FROM SCM_MGR.SCM_ADM_USER_MNU_EDIT_AUTH_V WHERE USER_ID='<TEST_USER>' AND MNU_ID='DMF0035' ORDER BY 2;
-- V12 앱 계정 EXECUTE + private synonym (기대: 객체별 SCMP_APP 각 1행 — 없으면 40_GRANT_SYNONYM.sql) — 부재 시 화면 "SQL ERROR"(PLS-00201)
SELECT 'V12-GRANT' G, TABLE_NAME, GRANTEE FROM ALL_TAB_PRIVS WHERE TABLE_SCHEMA='SCM_MGR' AND PRIVILEGE='EXECUTE' AND GRANTEE='SCMP_APP' AND TABLE_NAME IN ('PKG_DMF0035','PKG_DMF0022','PKG_DMF0051','PKG_SCM0002','FN_GET_DM_MKT_OWNER_NAME','FN_NEXT_DAY','UF_FX_STRING_SPLIT','PR_SCM_SYS_LOG_BATCH','FN_SPLITSTRING','FN_SCM_SYS_NVL','SCM_ARR_SPL_CNT','SCM_ARR_SPL_VAL','DMF0073_GET_VERSION_SALESPRICE') ORDER BY 2;
SELECT 'V12-SYN' G, SYNONYM_NAME FROM ALL_SYNONYMS WHERE OWNER='SCMP_APP' AND TABLE_OWNER='SCM_MGR' AND SYNONYM_NAME IN ('PKG_DMF0035','PKG_DMF0022','PKG_DMF0051','PKG_SCM0002','FN_GET_DM_MKT_OWNER_NAME','FN_NEXT_DAY','UF_FX_STRING_SPLIT','PR_SCM_SYS_LOG_BATCH','FN_SPLITSTRING','FN_SCM_SYS_NVL','SCM_ARR_SPL_CNT','SCM_ARR_SPL_VAL','DMF0073_GET_VERSION_SALESPRICE') ORDER BY 2;
-- V13 PKG 본문이 V_PROGRAM_ID 로 읽는 종속 PROGRAM_ID 전부의 시트 메타 (기대: 각 PROGRAM_ID 행 > 0 — 사내 값은 22/22A 파일 주석)
SELECT 'V13-META' G, PROGRAM_ID, 'COLUMNS' T, COUNT(*) CNT FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID IN ('DMF0022','DMF0035','DMF0051') GROUP BY PROGRAM_ID
UNION ALL SELECT 'V13-META', PROGRAM_ID, 'MEASURE', COUNT(*) FROM SCM_MGR.SCM_MST_SHEET_MEASURE WHERE PROGRAM_ID IN ('DMF0022','DMF0035','DMF0051') GROUP BY PROGRAM_ID ORDER BY 2,3;
-- V14 (2026-08-28 S7 계보) 동일 MNU_URL / ROUTE_PATH 를 가진 **타 MNU_ID** — 기대 0행. 있으면 그 메뉴로 진입 시 DMF0035 컴포넌트가 타 MNU_ID 배선으로 떠 오류 없이 0행 (QA 실사고: SCM0020)
SELECT 'V14-DUPURL' G, MNU_ID, UPPR_MNU_ID, MNU_URL, ROUTE_PATH, USE_YN FROM SCM_MGR.SCM_ADM_MNU_M
 WHERE MNU_ID <> 'DMF0035' AND (MNU_URL = 'demand-plan-waterfall' OR ROUTE_PATH LIKE '%demand-plan-waterfall%');
